    "questionAr": "وضع جسم كتلته $m = 10\\text{ كجم}$ على أرضية مصعد صاعد رأسياً بعجلة منتظمة $a = 2\\text{ م/ث}^2$. أوجد رد فعل أرضية المصعد على الجسم بالنيوتن (اعتبر $g = 9.8\\text{ م/ث}^2$).",
