    "titleAr": "قوة الدفع لكتلة متغيرة مع الزمن رقم 1",
    "difficulty": "hots",
    "questionEn": "A body moves in a straight line gathering matter such that its mass at time $t$ is $m(t) = 100 + 1t\\text{ kg}$, and its velocity is $v(t) = 20t\\text{ m/s}$. Find the net force acting on the body at $t = 5\\text{ s}$.",
    "questionAr": "يتحرك جسم في خط مستقيم بحيث تتجمع عليه المادة وتزداد كتلته مع الزمن بالعلاقة $m(t) = 100 + 1t\\text{ كجم}$، وكانت سرعته $v(t) = 20t\\text{ م/ث}$. أوجد محصلة القوة المؤثرة على الجسم عند $t = 5\\text{ ث}$.",
    "optionsEn": [
      "$2200\\text{ N}$",
      "$2300\\text{ N}$",
      "$2400\\text{ N}$",
      "$2500\\text{ N}$"
    ],
    "optionsAr": [
      "2200 نيوتن",
      "2300 نيوتن",
      "2400 نيوتن",
      "2500 نيوتن"
    ],
    "correctAnswer": "$2200\\text{ N}$",
    "correctIndex": 0,
    "hintEn": "By Newton's second law for variable mass, $F(t) = \\frac{d}{dt}[m(t) \\cdot v(t)]$.",
    "hintAr": "من قانون نيوتن الثاني للكتلة المتغيرة: $F(t) = \\frac{d}{dt}[m(t) \\cdot v(t)]$.",
    "stepByStepSolutionEn": [
      "1. Linear momentum: $H(t) = m(t) v(t) = (100 + 1t)(20t) = 2000t + 20t^2$.",
      "2. Net force: $F(t) = \\frac{dH}{dt} = 2000 + 40t$.",
      "3. At $t = 5\\text{ s}$: $F(5) = 2000 + 40(5) = 2000 + 200 = 2200\\text{ N}$."
    ],
    "stepByStepSolutionAr": [
      "١. كمية الحركة: $H(t) = (100 + 1t)(20t) = 2000t + 20t^2$.",
      "٢. القوة: $F(t) = \\frac{dH}{dt} = 2000 + 40t$.",
      "٣. عند $t = 5\\text{ ث}$: $F(5) = 2000 + 200 = 2200\\text{ نيوتن}$."
    ],
    "teacherTipEn": "Always use F = d(mv)/dt when mass varies with time.",
    "teacherTipAr": "استخدم دائماً ق = د(ك ع)/دن كلما كانت الكتلة متغيرة مع الزمن."
